WITH base AS (SELECT id, order_date, status, channel, amount, shipping_fee, CAST(shipping_fee AS INT) AS shipping_fee_int, discount - amount AS discount_minus_amount FROM orders WHERE discount <= 0.11) SELECT status, CASE WHEN shipping_fee_int >= 64 THEN 'PREMIUM' ELSE 'STANDARD' END AS shipping_fee_int_tier, SIZE(COLLECT_SET(status)) AS num_status, SORT_ARRAY(COLLECT_SET(status)) AS status_list, APPROX_PERCENTILE(shipping_fee_int, 0.5) AS shipping_fee_int_p50 FROM base GROUP BY 1, 2;
